const settings=["pdVoltage"],float_settings=["servoVoltageCoefficient","busVoltageCoefficient"];function powerSetup(){for(setting in settings)document.getElementById(setting).value=userSettings[setting];for(setting in float_settings)document.getElementById(setting).value=userSettings[setting]}function wsPowerStatus(e){var t=e.message,n=t.vbus,s=t.vservo,o=parseFloat(document.getElementById("busVoltageCoefficient").value),g=parseFloat(document.getElementById("servoVoltageCoefficient").value);document.getElementById("busVoltage").value=`${n*o}V [${n}v]`,document.getElementById("servoVoltage").value=`${s*g}V [${s}v]`}function togglePowerSettings(e){for(var t=document.getElementsByClassName("powerOnly"),n=0;n<t.length;n++)batteryOnly[n].style.display=e?"flex":"none"}function setPowerSettings(){for(f in float_settings)userSettings[f]=parseFloat(document.getElementById(f).value);for(s in settings)userSettings[s]=document.getElementById(s).value;setRestartRequired(),updateUserSettings()}